import{_ as t,a as r,o as d,a6 as o}from"./chunks/framework.CJDy2q7X.js";const p=JSON.parse(`{"title":"Get Customer Orders","description":"","frontmatter":{"outline":false,"examples":[{"id":"get-customer-orders","title":"Get Customer Orders","description":"Retrieve the authenticated customer's orders, newest first.","request":"GET /api/shop/customer-orders\\nX-STOREFRONT-KEY: pk_storefront_PvlE42nWGsKRVIf8bDlJngTPAdWAZbIy\\nAuthorization: Bearer 12|Iy8NExampleCustomerAccessToken\\n","response":"HTTP/1.1 200 OK\\n\\n[\\n  {\\n    \\"id\\": 384,\\n    \\"incrementId\\": \\"383\\",\\n    \\"status\\": \\"pending\\",\\n    \\"channelName\\": \\"Default\\",\\n    \\"customerEmail\\": \\"john.doe@example.com\\",\\n    \\"customerFirstName\\": \\"John\\",\\n    \\"customerLastName\\": \\"Doe\\",\\n    \\"shippingMethod\\": \\"flatrate_flatrate\\",\\n    \\"shippingTitle\\": \\"Flat Rate - Flat Rate\\",\\n    \\"couponCode\\": null,\\n    \\"totalItemCount\\": 1,\\n    \\"totalQtyOrdered\\": 1,\\n    \\"grandTotal\\": 65.99,\\n    \\"baseGrandTotal\\": 65.99,\\n    \\"subTotal\\": 55.99,\\n    \\"baseSubTotal\\": 55.99,\\n    \\"taxAmount\\": 0,\\n    \\"shippingAmount\\": 10,\\n    \\"discountAmount\\": 0,\\n    \\"baseCurrencyCode\\": \\"USD\\",\\n    \\"orderCurrencyCode\\": \\"USD\\",\\n    \\"createdAt\\": \\"2026-07-21T18:01:34+05:30\\",\\n    \\"updatedAt\\": \\"2026-07-21T18:01:34+05:30\\"\\n  }\\n]\\n","commonErrors":[{"error":"401 Unauthorized","cause":"The request carried no customer Bearer token, or the token has been revoked","solution":"Log in and send the returned token as Authorization Bearer"},{"error":"Empty array","cause":"The customer has placed no orders, or the status filter matched nothing","solution":"Drop the status filter, or check the value against the status list on this page"}]},{"id":"get-customer-orders-status","title":"Filter by Status","description":"Return only the orders in one status. Status is the single filter this endpoint accepts.","request":"GET /api/shop/customer-orders?status=processing\\nX-STOREFRONT-KEY: pk_storefront_PvlE42nWGsKRVIf8bDlJngTPAdWAZbIy\\nAuthorization: Bearer 12|Iy8NExampleCustomerAccessToken\\n","response":"HTTP/1.1 200 OK\\n\\n[\\n  {\\n    \\"id\\": 362,\\n    \\"incrementId\\": \\"361\\",\\n    \\"status\\": \\"processing\\",\\n    \\"channelName\\": \\"Default\\",\\n    \\"customerEmail\\": \\"john.doe@example.com\\",\\n    \\"customerFirstName\\": \\"John\\",\\n    \\"customerLastName\\": \\"Doe\\",\\n    \\"shippingMethod\\": \\"free_free\\",\\n    \\"shippingTitle\\": \\"Free Shipping - Free Shipping\\",\\n    \\"couponCode\\": null,\\n    \\"totalItemCount\\": 2,\\n    \\"totalQtyOrdered\\": 3,\\n    \\"grandTotal\\": 149.5,\\n    \\"baseGrandTotal\\": 149.5,\\n    \\"subTotal\\": 149.5,\\n    \\"baseSubTotal\\": 149.5,\\n    \\"taxAmount\\": 0,\\n    \\"shippingAmount\\": 0,\\n    \\"discountAmount\\": 0,\\n    \\"baseCurrencyCode\\": \\"USD\\",\\n    \\"orderCurrencyCode\\": \\"USD\\",\\n    \\"createdAt\\": \\"2026-07-14T11:22:07+05:30\\",\\n    \\"updatedAt\\": \\"2026-07-16T09:05:41+05:30\\"\\n  }\\n]\\n","commonErrors":[{"error":"Empty array","cause":"No order of the customer is in that status","solution":"Query without the filter to see which statuses the customer's orders actually carry"}]}]},"headers":[],"relativePath":"api/rest-api/shop/customer-orders/get-customer-orders.md","filePath":"api/rest-api/shop/customer-orders/get-customer-orders.md","lastUpdated":1787725411000}`),a={name:"api/rest-api/shop/customer-orders/get-customer-orders.md"};function s(n,e,c,i,l,u){return d(),r("div",null,e[0]||(e[0]=[o('<h1 id="get-customer-orders" tabindex="-1">Get Customer Orders <a class="header-anchor" href="#get-customer-orders" aria-label="Permalink to &quot;Get Customer Orders&quot;">​</a></h1><p>Return the order history of the authenticated customer.</p><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /api/shop/customer-orders</span></span></code></pre></div><h2 id="request-headers" tabindex="-1">Request Headers <a class="header-anchor" href="#request-headers" aria-label="Permalink to &quot;Request Headers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Header</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>X-STOREFRONT-KEY</code></td><td>Yes</td><td>Your storefront API key</td></tr><tr><td><code>Authorization</code></td><td>Yes</td><td>Bearer token of the logged-in customer</td></tr></tbody></table><h2 id="query-parameters" tabindex="-1">Query Parameters <a class="header-anchor" href="#query-parameters" aria-label="Permalink to &quot;Query Parameters&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>status</code></td><td>string</td><td>Return only orders in this status. Matched exactly against the stored value.</td></tr></tbody></table><p>Orders come back newest first, ten per response, and that page size is fixed — <code>page</code>, <code>per_page</code>, <code>limit</code>, and <code>sort</code> are accepted by the URL but have no effect on the result. Walk a longer history over GraphQL, where the same data is a cursor connection driven by <code>first</code> and <code>after</code>.</p><h2 id="response" tabindex="-1">Response <a class="header-anchor" href="#response" aria-label="Permalink to &quot;Response&quot;">​</a></h2><p>The response is a bare JSON array of orders. There is no wrapper object, no <code>data</code> key, and no pagination metadata block.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>integer</td><td>Order ID. Use it on <a href="/api/rest-api/shop/customer-orders/get-customer-order.html">Get Order Details</a>.</td></tr><tr><td><code>incrementId</code></td><td>string</td><td>Human-facing order number shown to the customer.</td></tr><tr><td><code>status</code></td><td>string</td><td>Current order status — see the list below.</td></tr><tr><td><code>channelName</code></td><td>string</td><td>Sales channel the order was placed on.</td></tr><tr><td><code>customerEmail</code></td><td>string</td><td>Email captured on the order.</td></tr><tr><td><code>customerFirstName</code> / <code>customerLastName</code></td><td>string</td><td>Name captured on the order.</td></tr><tr><td><code>shippingMethod</code></td><td>string</td><td>Method code, e.g. <code>flatrate_flatrate</code>.</td></tr><tr><td><code>shippingTitle</code></td><td>string</td><td>Human-readable method label.</td></tr><tr><td><code>couponCode</code></td><td>string</td><td>Coupon applied at checkout, <code>null</code> when none was used.</td></tr><tr><td><code>totalItemCount</code></td><td>integer</td><td>Number of distinct line items.</td></tr><tr><td><code>totalQtyOrdered</code></td><td>integer</td><td>Sum of the quantities across those lines.</td></tr><tr><td><code>grandTotal</code> / <code>baseGrandTotal</code></td><td>decimal</td><td>Order total in the order currency and in the store&#39;s base currency.</td></tr><tr><td><code>subTotal</code> / <code>baseSubTotal</code></td><td>decimal</td><td>Line-item total before tax, shipping, and discount.</td></tr><tr><td><code>taxAmount</code></td><td>decimal</td><td>Tax charged.</td></tr><tr><td><code>shippingAmount</code></td><td>decimal</td><td>Shipping charged.</td></tr><tr><td><code>discountAmount</code></td><td>decimal</td><td>Discount applied.</td></tr><tr><td><code>orderCurrencyCode</code> / <code>baseCurrencyCode</code></td><td>string</td><td>Currency the order was placed in, and the store&#39;s base currency.</td></tr><tr><td><code>createdAt</code> / <code>updatedAt</code></td><td>string</td><td>ISO 8601 timestamps.</td></tr></tbody></table><p>Amounts are raw numbers, not formatted strings — apply the currency symbol from <code>orderCurrencyCode</code> on the client.</p><h2 id="order-status-values" tabindex="-1">Order Status Values <a class="header-anchor" href="#order-status-values" aria-label="Permalink to &quot;Order Status Values&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Status</th><th>Meaning</th></tr></thead><tbody><tr><td><code>pending</code></td><td>Placed, payment not yet confirmed.</td></tr><tr><td><code>pending_payment</code></td><td>Awaiting an offline payment such as a bank transfer.</td></tr><tr><td><code>processing</code></td><td>Payment confirmed, order being prepared.</td></tr><tr><td><code>completed</code></td><td>Fully invoiced and shipped.</td></tr><tr><td><code>canceled</code></td><td>Canceled before fulfilment.</td></tr><tr><td><code>closed</code></td><td>Fully refunded.</td></tr><tr><td><code>fraud</code></td><td>Flagged by the store as fraudulent.</td></tr></tbody></table><h2 id="use-cases" tabindex="-1">Use Cases <a class="header-anchor" href="#use-cases" aria-label="Permalink to &quot;Use Cases&quot;">​</a></h2><ul><li><strong>Account order history</strong> — call the endpoint with no parameters and render the array; the newest order is already first, so no client-side sort is needed.</li><li><strong>&quot;Open orders&quot; tab</strong> — a status filter is one value only, so an open-orders view needs one call per status (<code>?status=pending</code>, <code>?status=processing</code>) merged on the client.</li><li><strong>Reorder shortcut</strong> — <code>id</code> from a row addresses <a href="/api/rest-api/shop/customer-orders/get-customer-order.html">Get Order Details</a>, which carries the line items needed to rebuild a cart.</li></ul><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><ul><li><strong>Read <code>incrementId</code>, not <code>id</code>, in the UI</strong> — <code>id</code> is the internal row identifier and does not match the number on the customer&#39;s confirmation email.</li><li><strong>Expect exactly ten rows</strong> — the endpoint neither paginates nor reports a total, so an account page needing the full history should use the GraphQL <code>customerOrders</code> connection.</li><li><strong>Compare <code>grandTotal</code> against <code>baseGrandTotal</code> before displaying</strong> — they diverge whenever the order was placed in a non-base currency, and only <code>grandTotal</code> matches what the customer paid.</li><li><strong>Treat an empty array as &quot;no orders&quot;, not an error</strong> — a customer with no purchases and an unmatched status filter both return <code>200</code> with <code>[]</code>.</li></ul><h2 id="related-resources" tabindex="-1">Related Resources <a class="header-anchor" href="#related-resources" aria-label="Permalink to &quot;Related Resources&quot;">​</a></h2><ul><li><a href="/api/rest-api/shop/customer-orders/get-customer-order.html">Get Order Details</a> — one order with its lines, addresses, and payment</li><li><a href="/api/rest-api/shop/checkout/place-order.html">Place Order</a> — turn the prepared cart into an order</li><li><a href="/api/rest-api/shop/customers/get-customer-profile.html">Get Customer Profile</a> — read the authenticated customer&#39;s account details</li></ul>',21)]))}const m=t(a,[["render",s]]);export{p as __pageData,m as default};
